    font-weight: 700;
    color: var(--text-primary);
  }

  .themes_wrap {
    display: flex;

    gap: var(--padding-md);

    button {
      width: 1rem;
      height: 1rem;
      border-radius: 50%;
      border: 1px solid var(--base-80);
      cursor: pointer;

      &:disabled {
        cursor: not-allowed;
        opacity: 0.7;
      }

      &:nth-of-type(1) {
        background-color: var(--white);
      }

      &:nth-of-type(2) {
        background-color: var(--black);
      }
    }
  }
}

